import 'dart:io';

import 'package:jnigen/jnigen.dart';

/// Generates Dart bindings for the app's own R&D benchmark Kotlin code
/// (`android/app/src/main/kotlin/.../bench/`) into
/// `lib/jni/bench_bindings.g.dart`.
///
/// Kept separate from `tool/jnigen.dart` so the Android SDK bindings used by
/// the app are never regenerated by R&D changes.
///
/// jnigen reads Kotlin from compiled `.class` files (it also reads Kotlin
/// metadata for nullability and `suspend`), so compile the app once first:
///
/// ```sh
/// flutter build apk --debug
/// dart run tool/jnigen_bench.dart
/// ```
Future<void> main() async {
  final packageRoot = Platform.script.resolve('../');
  final kotlinClasses = packageRoot.resolve(
    'build/app/tmp/kotlin-classes/debug/',
  );
  if (!Directory.fromUri(kotlinClasses).existsSync()) {
    stderr.writeln(
      'No compiled Kotlin classes at ${kotlinClasses.toFilePath()}. '
      'Run `flutter build apk --debug` first.',
    );
    exitCode = 1;
    return;
  }

  final generator = JniGenerator(
    input: Input(
      classPath: [kotlinClasses],
      classes: ['com.example.ffi_gen_jni_gen.bench'],
      androidSdk: AndroidSdk(addGradleDeps: true, androidExample: packageRoot),
    ),
    output: Output(
      dart: DartOutput(
        path: packageRoot.resolve('lib/jni/bench_bindings.g.dart'),
        structure: OutputStructure.singleFile,
      ),
    ),
  );
  await generator.generate();
}
